(() => {
  const el = document.getElementById('__NEXT_DATA__');
  if (!el) return JSON.stringify({err:'no __NEXT_DATA__'});
  const t = el.textContent || '';
  let d = null; try { d = JSON.parse(t); } catch(e) { return JSON.stringify({err:'parse', len:t.length}); }
  const pp = (d.props && d.props.pageProps) || {};
  const keys = Object.keys(pp);
  const brief = {};
  for (const k of keys) {
    const v = pp[k];
    brief[k] = Array.isArray(v) ? 'array[' + v.length + ']' : (v && typeof v === 'object') ? 'object{' + Object.keys(v).slice(0,8).join(',') + '}' : String(v).slice(0,40);
  }
  return JSON.stringify({len: t.length, keys, brief}, null, 1);
})()
